// Package database stores perago's queue, failed jobs, batches and cache in a SQL database through
// migro, so it runs on every migro dialect: PostgreSQL, CockroachDB, Redshift, MySQL, MariaDB,
// SQLite, SQL Server and Oracle.
//
// Create the tables with migrations generated by `make:queue-table`, `make:queue-failed-table`,
// `make:queue-batches-table` and `make:cache-table`, or at startup with Install.
package database

import (
	"context"
	"strconv"
	"strings"

	"github.com/LouisRiverstone/migro"
	"github.com/LouisRiverstone/migro/schema"
)

// Default table names (Laravel's).
const (
	JobsTable    = "jobs"
	FailedTable  = "failed_jobs"
	BatchesTable = "job_batches"
	CacheTable   = "cache"
)

// Tables names the tables Install creates; empty names use the defaults.
type Tables struct {
	Jobs, Failed, Batches, Cache string
}

func or(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

// Install creates every table that does not exist yet.
func Install(ctx context.Context, db *migro.DB, t Tables) error {
	s := schema.New(db)
	steps := []struct {
		name   string
		create func(context.Context, *schema.Builder, string) error
	}{
		{or(t.Jobs, JobsTable), CreateJobsTable},
		{or(t.Failed, FailedTable), CreateFailedJobsTable},
		{or(t.Batches, BatchesTable), CreateBatchesTable},
		{or(t.Cache, CacheTable), CreateCacheTable},
	}
	for _, st := range steps {
		ok, err := s.HasTable(ctx, st.name)
		if err != nil {
			return err
		}
		if ok {
			continue
		}
		if err := st.create(ctx, s, st.name); err != nil {
			return err
		}
	}
	return nil
}

// CreateJobsTable creates the queue table (make:queue-table).
func CreateJobsTable(ctx context.Context, s *schema.Builder, name string) error {
	name = or(name, JobsTable)
	err := s.CreateTable(ctx, name, func(t *schema.Table) {
		t.BigIncrements("id")
		t.String("queue").NotNull().Index()
		t.Text("payload").NotNull()
		t.Integer("attempts").NotNull().Default(0)
		t.BigInteger("reserved_at").Nullable()
		t.BigInteger("available_at").NotNull()
		t.BigInteger("created_at").NotNull()
		t.Index("queue", "reserved_at", "available_at")
	})
	if err != nil {
		return err
	}
	return widenText(ctx, s, name, "payload")
}

// CreateFailedJobsTable creates the failed jobs table (make:queue-failed-table).
func CreateFailedJobsTable(ctx context.Context, s *schema.Builder, name string) error {
	name = or(name, FailedTable)
	err := s.CreateTable(ctx, name, func(t *schema.Table) {
		t.String("uuid", 36).Primary()
		t.String("connection").NotNull()
		t.String("queue").NotNull().Index()
		t.Text("payload").NotNull()
		t.Text("exception").NotNull()
		t.BigInteger("failed_at").NotNull().Index()
	})
	if err != nil {
		return err
	}
	return widenText(ctx, s, name, "payload", "exception")
}

// CreateBatchesTable creates the job batches table (make:queue-batches-table).
func CreateBatchesTable(ctx context.Context, s *schema.Builder, name string) error {
	name = or(name, BatchesTable)
	err := s.CreateTable(ctx, name, func(t *schema.Table) {
		t.String("id", 36).Primary()
		t.String("name").NotNull()
		t.Integer("total_jobs").NotNull()
		t.Integer("pending_jobs").NotNull()
		t.Integer("failed_jobs").NotNull()
		t.Text("failed_job_ids").NotNull()
		t.Text("options").Nullable()
		t.BigInteger("cancelled_at").Nullable()
		t.BigInteger("created_at").NotNull().Index()
		t.BigInteger("finished_at").Nullable()
	})
	if err != nil {
		return err
	}
	return widenText(ctx, s, name, "failed_job_ids", "options")
}

// CacheValueLength is the longest value the database cache stores.
const CacheValueLength = 4000

// CreateCacheTable creates the cache table used for locks, rate limits and worker signals
// (make:cache-table).
func CreateCacheTable(ctx context.Context, s *schema.Builder, name string) error {
	return s.CreateTable(ctx, or(name, CacheTable), func(t *schema.Table) {
		t.String("key").Primary()
		t.String("value", CacheValueLength).NotNull()
		t.BigInteger("expiration").NotNull().Index()
	})
}

// widenText turns TEXT columns into LONGTEXT on MySQL and MariaDB, where TEXT stops at 64 KB.
func widenText(ctx context.Context, s *schema.Builder, table string, cols ...string) error {
	d := s.DB().Dialect
	if !isMySQL(d.Name()) {
		return nil
	}
	for _, c := range cols {
		if err := s.Raw(ctx, "ALTER TABLE "+d.Quote(table)+" MODIFY "+d.Quote(c)+" LONGTEXT"+nullability(table, c)); err != nil {
			return err
		}
	}
	return nil
}

func nullability(table, col string) string {
	if col == "options" {
		return " NULL"
	}
	return " NOT NULL"
}

func isMySQL(name string) bool { return name == "mysql" || name == "mariadb" }

// sqlBuilder renders the few statements the stores need, quoted for the dialect.
type sqlBuilder struct {
	db    *migro.DB
	table string
}

func (b sqlBuilder) q(ident string) string { return b.db.Dialect.Quote(ident) }

func (b sqlBuilder) t() string { return b.q(b.table) }

func (b sqlBuilder) cols(names ...string) string {
	out := make([]string, len(names))
	for i, n := range names {
		out[i] = b.q(n)
	}
	return strings.Join(out, ", ")
}

// limit wraps "SELECT <rest>" so it returns at most n rows.
func (b sqlBuilder) limit(rest string, n int) string {
	switch b.db.Dialect.Name() {
	case "sqlserver":
		return "SELECT TOP (" + strconv.Itoa(n) + ") " + rest
	case "oracle":
		return "SELECT " + rest + " FETCH FIRST " + strconv.Itoa(n) + " ROWS ONLY"
	}
	return "SELECT " + rest + " LIMIT " + strconv.Itoa(n)
}

func (b sqlBuilder) insert(cols ...string) string {
	marks := strings.TrimSuffix(strings.Repeat("?, ", len(cols)), ", ")
	return "INSERT INTO " + b.t() + " (" + b.cols(cols...) + ") VALUES (" + marks + ")"
}
